using Suishouyi.Core;
namespace Suishouyi.App;
internal sealed class SettingsWindow:Form {
 ComboBox model=new();bool changing;
 public void UpdateModel(string id){changing=true;if(!model.Items.Contains(id))model.Items.Add(id);model.SelectedItem=id;changing=false;}
 public SettingsWindow(AppSettings settings,IReadOnlyList<string> catalog,Action<string> modelChanged,Action<string> themeChanged,Func<int,uint,int,uint,bool> hotkeysChanged,Action refresh) {
  Text="随手译设置";Size=new(500,420);FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;StartPosition=FormStartPosition.CenterScreen;Font=new("Microsoft YaHei UI",10);Padding=new(22);
  var list=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true};Controls.Add(list);
  list.Controls.Add(new Label{Text="AI 模型（实际可用性以当前账号为准）",AutoSize=true});model=new ComboBox{Width=420,DropDownStyle=ComboBoxStyle.DropDownList};model.Items.AddRange(catalog.Append(settings.SelectedModelId).Distinct().Cast<object>().ToArray());model.SelectedItem=settings.SelectedModelId;model.SelectedIndexChanged+=(_,_)=>{if(!changing&&model.SelectedItem is string id)modelChanged(id);};list.Controls.Add(model);if(!catalog.Contains(settings.SelectedModelId))list.Controls.Add(new Label{Text="保存的模型未出现在目录中，请刷新或重新确认。",AutoSize=true});
  var modelButtons=new FlowLayoutPanel{Width=420,Height=35};var reload=new Button{Text="刷新模型列表",AutoSize=true};reload.Click+=(_,_)=>refresh();var reset=new Button{Text="恢复 hy3",AutoSize=true};reset.Click+=(_,_)=>{if(!model.Items.Contains("hy3"))model.Items.Add("hy3");model.SelectedItem="hy3";};modelButtons.Controls.AddRange(new Control[]{reload,reset});list.Controls.Add(modelButtons);
  list.Controls.Add(new Label{Text="外观",AutoSize=true});var themes=new ComboBox{Width=420,DropDownStyle=ComboBoxStyle.DropDownList};themes.Items.AddRange(new object[]{"简洁精致","深色科技"});themes.SelectedIndex=settings.ThemeId=="techDark"?1:0;themes.SelectedIndexChanged+=(_,_)=>{var id=themes.SelectedIndex==1?"techDark":"refinedLight";themeChanged(id);Theme.Get(id).Apply(this);};list.Controls.Add(themes);
  var rows=new List<(ComboBox key,CheckBox ctrl,CheckBox shift,CheckBox alt)>();
  void Row(string title,int key,uint modifiers){var row=new FlowLayoutPanel{Width=430,Height=34};row.Controls.Add(new Label{Text=title,Width=55});var keys=new ComboBox{Width=100,DropDownStyle=ComboBoxStyle.DropDownList};keys.Items.AddRange(Enumerable.Range(65,26).Concat(Enumerable.Range(112,12)).Select(v=>((Keys)v).ToString()).Cast<object>().ToArray());keys.SelectedItem=((Keys)key).ToString();var ctrl=new CheckBox{Text="Ctrl",Width=65,Checked=(modifiers&2)!=0};var shift=new CheckBox{Text="Shift",Width=65,Checked=(modifiers&4)!=0};var alt=new CheckBox{Text="Alt",Width=65,Checked=(modifiers&1)!=0};row.Controls.AddRange(new Control[]{keys,ctrl,shift,alt});list.Controls.Add(row);rows.Add((keys,ctrl,shift,alt));}
  list.Controls.Add(new Label{Text="全局快捷键",AutoSize=true});Row("翻译",settings.TranslationKey,settings.TranslationModifiers);Row("解释",settings.ExplanationKey,settings.ExplanationModifiers);
  var save=new Button{Text="应用快捷键",AutoSize=true};save.Click+=(_,_)=>{uint Mods(int i)=>(uint)((rows[i].ctrl.Checked?2:0)|(rows[i].shift.Checked?4:0)|(rows[i].alt.Checked?1:0));if(Mods(0)==0||Mods(1)==0){MessageBox.Show("请选择 Ctrl、Shift 或 Alt 修饰键。");return;}var a=(int)Enum.Parse<Keys>((string)rows[0].key.SelectedItem!);var b=(int)Enum.Parse<Keys>((string)rows[1].key.SelectedItem!);if(hotkeysChanged(a,Mods(0),b,Mods(1)))MessageBox.Show("快捷键已保存。");else MessageBox.Show("快捷键已被占用，请换一组；托盘菜单仍可使用。");};var defaults=new Button{Text="恢复默认快捷键",AutoSize=true};defaults.Click+=(_,_)=>{rows[0].key.SelectedItem="F8";rows[1].key.SelectedItem="F9";foreach(var row in rows){row.ctrl.Checked=row.shift.Checked=true;row.alt.Checked=false;}save.PerformClick();};var actions=new FlowLayoutPanel{Width=430,Height=36};actions.Controls.AddRange(new Control[]{save,defaults});list.Controls.Add(actions);Theme.Get(settings.ThemeId).Apply(this);
 }
}
